(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {title:$('titleScreen'),levels:$('levelScreen'),pause:$('pauseScreen'),result:$('resultScreen'),hud:$('hud'),beat:$('beatIndicator'),toast:$('toast'),mobile:$('mobileControls'),hint:$('controlsHint')};
  const W=960,H=540,GROUND=430,BEAT=.72;
  const levels=[
    {name:'VILA DOS TELHADOS',title:'Vila dos telhados',sky:['#efad79','#bb6a69','#675064'],ground:'#27303a',accent:'#f2d18a',length:4100,beat:BEAT,obstacles:[[440,'box'],[750,'gap'],[1020,'box'],[1340,'low'],[1700,'gap'],[1940,'box'],[2310,'low'],[2650,'gap'],[2910,'box'],[3270,'low'],[3580,'gap']],notes:[320,560,835,1110,1260,1510,1810,2110,2450,2770,3100,3460,3790],grabs:[[860,990],[1970,2090],[3000,3140]]},
    {name:'FLORESTA SUSSURRANTE',title:'Floresta sussurrante',sky:['#b8d48e','#719875','#284d4b'],ground:'#253d37',accent:'#dded9e',length:4500,beat:BEAT*.92,obstacles:[[490,'box'],[820,'gap'],[1120,'low'],[1430,'gap'],[1720,'box'],[2060,'low'],[2380,'gap'],[2700,'box'],[3020,'gap'],[3330,'low'],[3670,'gap'],[3980,'box']],notes:[280,610,940,1270,1580,1900,2200,2550,2870,3200,3520,3850,4170],grabs:[[835,1030],[1425,1600],[2350,2530],[3000,3180],[3640,3820]]},
    {name:'RUÍNAS DO ECO',title:'Ruínas do eco',sky:['#e4b979','#b57c59','#675152'],ground:'#40373a',accent:'#f3d28b',length:4900,beat:BEAT*.84,obstacles:[[420,'low'],[730,'gap'],[1020,'box'],[1340,'gap'],[1640,'low'],[1940,'gap'],[2240,'box'],[2570,'low'],[2880,'gap'],[3190,'box'],[3500,'gap'],[3820,'low'],[4150,'gap'],[4450,'box']],notes:[280,570,880,1180,1480,1780,2080,2390,2700,3000,3320,3630,3950,4260,4600],grabs:[[700,870],[1320,1500],[1910,2090],[2860,3050],[3480,3670],[4120,4310]]}
  ];
  let selected=0,mode='title',last=0,elapsed=0,worldX=0,player,items=[],keys={},beatElapsed=0,toastUntil=0,shake=0,slow=1,soundOn=false,audioCtx=null,lastBeatNumber=-1;
  const saved=JSON.parse(localStorage.getItem('ritmoFelinoBest')||'{}');
  let audioButton=$('soundToggle');
  function show(screen){for(const key of ['title','levels','pause','result'])ui[key].hidden=key!==screen;}
  function startGame(){
    const cfg=levels[selected];mode='playing';elapsed=0;worldX=0;beatElapsed=0;slow=1;shake=0;lastBeatNumber=-1;
    items=cfg.notes.map(x=>({x,y:GROUND-72,got:false,phase:Math.random()*6}));
    player={x:170,y:GROUND-43,vy:0,w:37,h:43,onGround:true,jumps:0,combo:0,bestCombo:0,notes:0,slide:0,hang:false,hangTimer:0,flash:0,spin:0};
    $('levelName').textContent=cfg.name;$('noteCount').textContent='0';$('comboCount').textContent='0';$('progressBar').style.width='0%';
    $('bestTime').textContent=saved[selected]?`RECORDE ${formatTime(saved[selected])}`:'RECORDE —';ui.hud.hidden=false;ui.beat.hidden=false;ui.mobile.hidden=false;ui.hint.style.display='';show(null);$('pauseButton').textContent='Ⅱ';
  }
  function formatTime(s){const m=Math.floor(s/60),sec=(s%60).toFixed(1).padStart(4,'0');return `${String(m).padStart(2,'0')}:${sec}`;}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastUntil=performance.now()+900;}
  function playTone(freq=660,duration=.08,type='sine',volume=.035){if(!soundOn)return;try{audioCtx ||=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration);}catch(e){}}
  function setSound(){soundOn=!soundOn;audioButton.innerHTML=`♫ <span>${soundOn?'ON':'ÁUDIO'}</span>`;if(soundOn){playTone(660,.1);toast('SOM ATIVADO');}}
  function getBeatDiff(){const cfg=levels[selected],phase=(elapsed%cfg.beat)/cfg.beat;return Math.min(phase,1-phase)*cfg.beat;}
  function jump(){if(mode!=='playing')return;if(player.hang){player.hang=false;player.vy=-525;player.jumps=1;player.combo=Math.max(0,player.combo);playTone(520,.1,'triangle');return;}if(player.onGround){player.vy=-490;player.onGround=false;player.jumps=1;player.slide=0;playTone(340,.08,'sine');return;}if(player.jumps===1){const diff=getBeatDiff();if(diff<.16){player.vy=-640;slow=1.16;player.combo++;player.bestCombo=Math.max(player.bestCombo,player.combo);toast('NO RITMO! +IMPULSO');playTone(880,.16,'triangle',.06);player.flash=.3;}else{player.vy=-355;player.combo=0;slow=.72;toast('FORA DO RITMO');playTone(170,.12,'square',.025);}player.jumps=2;player.spin=.28;$('comboCount').textContent=player.combo;return;}}
  function grab(){if(mode!=='playing')return;const cfg=levels[selected],wx=worldX+player.x;const zone=cfg.grabs.find(([a,b])=>wx>a&&wx<b);if(zone&&!player.onGround){player.hang=true;player.vy=0;player.hangTimer=0;player.jumps=0;toast('AGARRADO! ↑ PARA SUBIR');playTone(440,.1,'triangle');}else if(player.onGround){player.slide=.65;}}
  function slide(){if(mode==='playing'){player.slide=.72;if(!player.onGround)player.vy+=250;}}
  function activate(action){if(action==='jump')jump();if(action==='grab')grab();if(action==='slide')slide();}
  function pause(){if(mode==='playing'){mode='paused';ui.hud.hidden=true;ui.beat.hidden=true;ui.mobile.hidden=true;show('pause');}else if(mode==='paused')resume();}
  function resume(){mode='playing';ui.hud.hidden=false;ui.beat.hidden=false;ui.mobile.hidden=false;show(null);last=performance.now();}
  function finish(){if(mode!=='playing')return;mode='result';ui.hud.hidden=true;ui.beat.hidden=true;ui.mobile.hidden=true;show('result');const newRecord=!saved[selected]||elapsed<saved[selected];if(newRecord){saved[selected]=elapsed;localStorage.setItem('ritmoFelinoBest',JSON.stringify(saved));} $('resultStamp').textContent=newRecord?'✦':'♫';$('resultEyebrow').textContent=newRecord?'NOVO RECORDE!':'CORRIDA CONCLUÍDA';$('resultTitle').textContent=player.bestCombo>=5?'No ritmo!':'Chegada perfeita!';$('resultMessage').textContent=player.bestCombo>=5?'Você e a música viraram uma coisa só.':'Cada batida te levou mais longe.';$('resultTime').textContent=formatTime(elapsed);$('resultNotes').textContent=`${player.notes} / ${items.length}`;$('resultCombo').textContent=player.bestCombo;playTone(740,.2,'triangle',.05);}
  function toggleLevelCards(){document.querySelectorAll('.level-card').forEach((el,i)=>el.classList.toggle('selected',i===selected));}
  function startFromTitle(){show('levels');mode='levels';ui.hud.hidden=true;ui.beat.hidden=true;ui.mobile.hidden=true;}
  function rgb(hex){return [parseInt(hex.slice(1,3),16),parseInt(hex.slice(3,5),16),parseInt(hex.slice(5,7),16)];}
  function mixColor(a,b,t){const x=rgb(a),y=rgb(b);return `rgb(${x.map((v,i)=>Math.round(v+(y[i]-v)*t)).join(',')})`;}
  function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
  function drawBackground(time){
    const cfg=levels[selected],g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,cfg.sky[0]);g.addColorStop(.58,cfg.sky[1]);g.addColorStop(1,cfg.sky[2]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.22;ctx.fillStyle='#fff0c8';ctx.beginPath();ctx.arc(756,127,45,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
    // Soft distant cloud wisps.
    for(let i=0;i<5;i++){const x=((i*247-worldX*.09)%1150+1150)%1150-80,y=80+(i%3)*49;ctx.fillStyle='#fff1d2';ctx.globalAlpha=.1;ctx.beginPath();ctx.ellipse(x,y,55,9,0,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    const forest=selected===1,ruins=selected===2;
    for(let layer=0;layer<3;layer++){
      const spacing=forest?118:ruins?176:184,offset=worldX*(.12+layer*.11),count=11;
      for(let i=-1;i<count;i++){const x=(i*spacing-offset%spacing),h=(forest?210:ruins?100:75)+((i*37+layer*31)%75);if(forest){ctx.fillStyle=['#365b4c','#2d5045','#24463e'][layer];ctx.beginPath();ctx.moveTo(x+spacing*.5,GROUND-h);ctx.lineTo(x+spacing*.16,GROUND+4);ctx.lineTo(x+spacing*.83,GROUND+4);ctx.fill();ctx.fillRect(x+spacing*.48,GROUND-h*.3,spacing*.04,h*.3);}else if(ruins){ctx.fillStyle=['#80645b','#725951','#624f50'][layer];ctx.fillRect(x+spacing*.25,GROUND-h,spacing*.3,h);ctx.fillRect(x+spacing*.1,GROUND-h-12,spacing*.6,14);ctx.fillStyle='#d3ad79';ctx.fillRect(x+spacing*.29,GROUND-h+28,spacing*.07,30);ctx.fillRect(x+spacing*.48,GROUND-h+28,spacing*.07,30);}else{ctx.fillStyle=['#9d5c62','#805762','#605364'][layer];ctx.fillRect(x+spacing*.16,GROUND-h,spacing*.67,h);ctx.beginPath();ctx.moveTo(x+spacing*.06,GROUND-h);ctx.lineTo(x+spacing*.5,GROUND-h-29);ctx.lineTo(x+spacing*.94,GROUND-h);ctx.fill();ctx.fillStyle='#d48a72';ctx.fillRect(x+spacing*.34,GROUND-h+20,7,9);ctx.fillRect(x+spacing*.66,GROUND-h+20,7,9);}}}
    ctx.fillStyle=cfg.ground;ctx.fillRect(0,GROUND,W,H-GROUND);ctx.fillStyle=cfg.accent;ctx.globalAlpha=.65;ctx.fillRect(0,GROUND,W,3);ctx.globalAlpha=1;
    for(let x=-((worldX*.9)%56);x<W;x+=56){ctx.fillStyle=selected===0?'#39404a':selected===1?'#304940':'#504446';ctx.fillRect(x,GROUND+25,31,2);ctx.fillStyle='#ffffff0a';ctx.fillRect(x+5,GROUND+54,20,2);}
    // Track scenery: platforms and gap pits scroll through the world.
    const start=Math.floor(worldX/320)*320;
    for(let wx=start;wx<worldX+W+400;wx+=320){const sx=wx-worldX;if(sx<-90)continue;const n=Math.floor(wx/320);if(n%3===1){ctx.fillStyle=selected===1?'#365d46':selected===2?'#76604b':'#745454';ctx.fillRect(sx+65,GROUND-85,120,85);ctx.fillStyle=cfg.accent;ctx.globalAlpha=.24;ctx.fillRect(sx+65,GROUND-85,120,5);ctx.globalAlpha=1;}}
  }
  function drawWorld(){const cfg=levels[selected],sxWorld=worldX;
    // Obstacles are drawn in world-space and skipped after passing.
    for(const [x,type] of cfg.obstacles){const sx=x-worldX;if(sx<-90||sx>W+90)continue;if(type==='gap'){ctx.fillStyle='#10131c';ctx.fillRect(sx,GROUND-1,86,H-GROUND+1);ctx.fillStyle='#ffffff0b';ctx.fillRect(sx+4,GROUND,78,5);continue;}if(type==='low'){ctx.fillStyle='#3b4146';rounded(sx,GROUND-25,48,25,8);ctx.fill();ctx.fillStyle=cfg.accent;ctx.globalAlpha=.35;ctx.fillRect(sx+8,GROUND-20,31,3);ctx.globalAlpha=1;}else{ctx.fillStyle=selected===1?'#61493d':selected===2?'#7b6550':'#76604d';rounded(sx,GROUND-49,42,49,5);ctx.fill();ctx.fillStyle=cfg.accent;ctx.globalAlpha=.35;ctx.fillRect(sx+6,GROUND-43,30,4);ctx.globalAlpha=1;}}
    for(const [a,b] of cfg.grabs){const sx=a-worldX,ex=b-worldX;if(ex<0||sx>W)continue;ctx.strokeStyle=selected===1?'#9cc67a':cfg.accent;ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(sx,GROUND-20);ctx.bezierCurveTo(sx-8,GROUND-130,ex+8,GROUND-160,ex,GROUND-240);ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#e7e1b5';ctx.globalAlpha=.55;ctx.beginPath();ctx.moveTo(sx+5,GROUND-17);ctx.bezierCurveTo(sx,GROUND-125,ex+13,GROUND-158,ex+6,GROUND-237);ctx.stroke();ctx.globalAlpha=1;}
    items.forEach(item=>{if(item.got)return;const x=item.x-worldX;if(x<-20||x>W+20)return;const y=item.y+Math.sin(elapsed*4+item.phase)*5;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(elapsed*2+item.phase)*.15);ctx.fillStyle='#d8fa70';ctx.shadowColor='#d8fa70';ctx.shadowBlur=14;ctx.font='bold 27px Outfit';ctx.fillText('♫',-9,9);ctx.restore();});
    // Cat running silhouette and golden eyes.
    const p=player;if(!p)return;let py=p.y;if(p.hang){py=GROUND-176+Math.sin(elapsed*4)*3;}const bob=p.onGround&&!p.slide?Math.sin(elapsed*19)*2:0;
    ctx.save();ctx.translate(p.x,py+bob);if(p.flash>0){ctx.shadowColor='#d8fa70';ctx.shadowBlur=26;}if(p.spin>0){ctx.rotate((.28-p.spin)*Math.PI*3);}
    ctx.fillStyle='#090b10';ctx.beginPath();ctx.ellipse(17,26,p.slide?23:16,p.slide?11:14,-.3,0,Math.PI*2);ctx.fill();
    ctx.lineWidth=6;ctx.strokeStyle='#090b10';ctx.lineCap='round';ctx.beginPath();ctx.moveTo(6,27);ctx.bezierCurveTo(-9,18,-8,4,1,1);ctx.stroke();
    if(p.slide){ctx.beginPath();ctx.ellipse(23,24,17,11,-.12,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(37,18,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e6ca55';ctx.fillRect(40,15,3,5);}
    else{ctx.beginPath();ctx.ellipse(18,25,14,18,-.18,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(24,12,14,12,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(13,6);ctx.lineTo(13,-6);ctx.lineTo(20,3);ctx.fill();ctx.beginPath();ctx.moveTo(26,3);ctx.lineTo(34,-5);ctx.lineTo(32,9);ctx.fill();ctx.fillStyle='#e6ca55';ctx.shadowColor='#e6ca55';ctx.shadowBlur=7;ctx.beginPath();ctx.ellipse(29,12,2.1,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e6ca55';ctx.beginPath();ctx.ellipse(21,12,2.1,4,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#a5a3a0';ctx.fillRect(33,18,7,1);ctx.fillRect(33,21,6,1);if(p.onGround){const step=Math.sin(elapsed*19)*4;ctx.strokeStyle='#090b10';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(12,37);ctx.lineTo(11+step,42);ctx.moveTo(25,38);ctx.lineTo(27-step,42);ctx.stroke();}}
    if(p.hang){ctx.strokeStyle='#090b10';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(16,3);ctx.lineTo(12,-5);ctx.moveTo(30,2);ctx.lineTo(35,-7);ctx.stroke();}
    ctx.restore();
    if(shake>0){ctx.fillStyle=`rgba(255,83,65,${shake*.45})`;ctx.fillRect(0,0,W,H);}
  }

  function update(dt,now){if(mode!=='playing')return;dt=Math.min(dt,.035);elapsed+=dt;const cfg=levels[selected],p=player;
    if(p.flash>0)p.flash=Math.max(0,p.flash-dt);if(p.spin>0)p.spin=Math.max(0,p.spin-dt);if(p.slide>0)p.slide=Math.max(0,p.slide-dt);if(shake>0)shake=Math.max(0,shake-dt);
    const beatNo=Math.floor(elapsed/cfg.beat);if(beatNo!==lastBeatNumber){lastBeatNumber=beatNo;playTone(220,.025,'sine',.009);}
    ui.timer.textContent=formatTime(elapsed);$('progressBar').style.width=`${Math.min(100,worldX/cfg.length*100)}%`;const phase=(elapsed%cfg.beat)/cfg.beat;ui.beat.classList.toggle('strong',phase<.12||phase>.88);
    if(now>toastUntil)ui.toast.classList.remove('show');
    const speed=(p.hang?0:220*slow)*(p.slide?1.12:1);if(!p.hang)worldX+=speed*dt;
    if(p.hang){p.hangTimer+=dt;if(p.hangTimer>2.2){p.hang=false;p.vy=30;}}
    else{p.vy+=1320*dt;p.y+=p.vy*dt;const floor=GROUND-p.h;if(p.y>=floor){p.y=floor;p.vy=0;if(!p.onGround){p.onGround=true;p.jumps=0;slow=1;}}else p.onGround=false;}
    for(const item of items){if(!item.got&&Math.abs(item.x-worldX-p.x)<23&&Math.abs(item.y-p.y-20)<57){item.got=true;p.notes++;$('noteCount').textContent=p.notes;toast(p.notes%4===0?'ATALHO ABERTO!':'NOTA COLETADA');playTone(990,.12,'triangle',.04);}}
    const wx=worldX+p.x;
    for(const [x,type] of cfg.obstacles){if(x<worldX-100||x>worldX+245)continue;const width=type==='gap'?86:type==='low'?48:42;const hitX=wx+18>x&&wx-13<x+width;const hitY=type==='low'?p.y+p.h>GROUND-28&&p.y<GROUND:p.y+p.h>GROUND-50;if(type==='gap'){if(hitX&&p.y+p.h>=GROUND-5&&!p.hang){shake=.3;worldX=Math.max(0,worldX-95);p.combo=0;$('comboCount').textContent='0';p.vy=-410;p.onGround=false;p.jumps=1;p.y=Math.min(p.y,GROUND-55);toast('SALTO! EVITE O VÃO');playTone(130,.13,'square',.04);break;}}else if(hitX&&hitY&&!p.slide){shake=.35;worldX=Math.max(0,worldX-75);p.vy=-300;p.onGround=false;p.jumps=0;p.combo=0;$('comboCount').textContent='0';toast('OPS! RECUPERE O RITMO');playTone(120,.15,'square',.04);break;}}
    // Landing beyond the end of a gap is safe; regular ground keeps auto-running.
    if(worldX>=cfg.length){finish();return;}
  }
  function drawTitleScene(t){const old=player,ox=worldX,oe=elapsed;worldX=t*.055;elapsed=t/1000;player={x:282,y:GROUND-62,vy:0,w:37,h:43,onGround:true,jumps:0,combo:0,bestCombo:0,notes:0,slide:0,hang:false,flash:0,spin:0};drawBackground(t); // larger editorial cat on the rooftop
    ctx.fillStyle='#252a31';ctx.fillRect(0,GROUND,960,110);ctx.fillStyle='#f2d18a';ctx.globalAlpha=.55;ctx.fillRect(0,GROUND,960,3);ctx.globalAlpha=1;
    ctx.fillStyle='#11151c';ctx.beginPath();ctx.moveTo(420,GROUND);ctx.lineTo(565,GROUND-118);ctx.lineTo(702,GROUND);ctx.fill();ctx.fillRect(439,GROUND-8,238,8);ctx.fillStyle='#e2b38b';ctx.globalAlpha=.35;ctx.fillRect(551,GROUND-77,20,24);ctx.globalAlpha=1;
    // rooftop flowers and note sparks
    for(let i=0;i<5;i++){const x=650+i*48,y=GROUND-10;ctx.fillStyle='#c9d98e';ctx.fillRect(x,y-18,2,18);ctx.fillStyle='#f3c7b2';ctx.beginPath();ctx.arc(x+1,y-20,4,0,Math.PI*2);ctx.fill();}
    player={...player,x:507,y:GROUND-78};drawCatOnly(player,t);player=old;worldX=ox;elapsed=oe;
  }
  function drawCatOnly(p,t){ctx.save();ctx.translate(p.x,p.y+Math.sin(t/350)*2);ctx.scale(1.7,1.7);ctx.fillStyle='#080a0e';ctx.beginPath();ctx.ellipse(17,26,16,14,-.3,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(6,27);ctx.bezierCurveTo(-10,22,-9,4,1,1);ctx.lineWidth=7;ctx.strokeStyle='#080a0e';ctx.stroke();ctx.beginPath();ctx.ellipse(18,25,14,18,-.18,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(24,12,14,12,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(13,6);ctx.lineTo(13,-6);ctx.lineTo(20,3);ctx.fill();ctx.beginPath();ctx.moveTo(26,3);ctx.lineTo(34,-5);ctx.lineTo(32,9);ctx.fill();ctx.fillStyle='#edcf53';ctx.shadowColor='#edcf53';ctx.shadowBlur=12;ctx.beginPath();ctx.ellipse(29,12,2.4,4,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(21,12,2.4,4,0,0,Math.PI*2);ctx.fill();ctx.restore();}
  function frame(now){const dt=(now-last)/1000||0;last=now;if(mode==='playing')update(dt,now);ctx.save();if(shake>0&&mode==='playing')ctx.translate((Math.random()-.5)*8*shake,(Math.random()-.5)*5*shake);if(mode==='title'||mode==='levels'){drawTitleScene(now);}else{drawBackground(now);if(player)drawWorld();}ctx.restore();requestAnimationFrame(frame);}
  document.getElementById('playButton').addEventListener('click',startFromTitle);
  $('howButton').addEventListener('click',()=>{toast('PULO DUPLO NO TEMPO DA BATIDA!');});
  $('backButton').addEventListener('click',()=>{mode='title';show('title');});
  document.querySelectorAll('.level-card').forEach(card=>card.addEventListener('click',()=>{selected=Number(card.dataset.level);toggleLevelCards();}));
  $('startLevelButton').addEventListener('click',startGame);
  $('pauseButton').addEventListener('click',pause);$('resumeButton').addEventListener('click',resume);$('restartButton').addEventListener('click',startGame);
  $('exitButton').addEventListener('click',()=>{mode='levels';ui.hud.hidden=true;show('levels');});
  $('againButton').addEventListener('click',startGame);$('resultLevelsButton').addEventListener('click',()=>{mode='levels';show('levels');});
  audioButton.addEventListener('click',setSound);
  window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;keys[e.code]=true;if(e.code==='Escape'||e.code==='KeyP'){pause();return;}if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')jump();if(e.code==='ArrowDown'||e.code==='KeyS')slide();if(e.code==='ShiftLeft'||e.code==='ShiftRight'||e.code==='KeyX'||e.code==='KeyE')grab();});
  window.addEventListener('keyup',e=>{keys[e.code]=false;});
  document.querySelectorAll('.mobile-controls button').forEach(button=>{const action=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);activate(action);});});
  let touchStart=null;canvas.addEventListener('touchstart',e=>{if(mode!=='playing')return;const touch=e.changedTouches[0];touchStart={x:touch.clientX,y:touch.clientY,time:Date.now()};},{passive:true});canvas.addEventListener('touchend',e=>{if(!touchStart||mode!=='playing')return;const dy=e.changedTouches[0].clientY-touchStart.y;if(dy>32)slide();else if(dy<-30)grab();else jump();touchStart=null;},{passive:true});
  let selected=0; // keep keyboard selection predictable on compact screens
  // D-pad left/right changes world selection while on the level picker.
  window.addEventListener('keydown',e=>{if(mode==='levels'&&(e.code==='ArrowLeft'||e.code==='ArrowRight')){selected=(selected+(e.code==='ArrowRight'?1:2))%3;toggleLevelCards();}});
  function resize(){const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
  window.addEventListener('resize',resize);resize();show('title');last=performance.now();requestAnimationFrame(frame);
})();

