(()=>{
  'use strict';
  const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=960,H=540,GROUND=430;
  const $=id=>document.getElementById(id);
  const ui={hud:$('hud'),level:$('levelName'),timer:$('timer'),best:$('bestTime'),beat:$('beatIndicator'),toast:$('toast')};
  const screens={title:$('titleScreen'),levels:$('levelScreen'),pause:$('pauseScreen'),result:$('resultScreen')};
  const palettes=[
    {name:'VILA DOS TELHADOS',beat:.62,sky:['#17233b','#754f62'],ground:'#32343d',accent:'#f2cf83',hill:'#252b3a'},
    {name:'FLORESTA SUSSURRANTE',beat:.54,sky:['#122b2b','#54715c'],ground:'#263b32',accent:'#c9df8b',hill:'#1c332d'},
    {name:'RUÍNAS DO ECO',beat:.48,sky:['#28213b','#a56e62'],ground:'#3a3440',accent:'#f2bd78',hill:'#302a3e'}
  ];
  const levels=[
    {length:8500,beat:.62,obstacles:[[600,'gap'],[1070,'low'],[1510,'block'],[2050,'gap'],[2640,'low'],[3120,'block'],[3700,'gap'],[4280,'low'],[4920,'block'],[5560,'gap'],[6320,'low'],[7040,'block'],[7760,'gap']],items:[350,850,1320,1850,2390,2890,3450,4020,4580,5240,5910,6630,7410,8110]},
    {length:9000,beat:.54,obstacles:[[650,'gap'],[1180,'block'],[1770,'low'],[2300,'gap'],[2910,'block'],[3500,'low'],[4050,'gap'],[4650,'block'],[5220,'low'],[5800,'gap'],[6440,'block'],[7080,'low'],[7720,'gap'],[8400,'block']],items:[400,940,1510,2080,2670,3260,3830,4410,5010,5590,6200,6840,7470,8110,8750]},
    {length:9400,beat:.48,obstacles:[[630,'block'],[1150,'gap'],[1710,'low'],[2240,'block'],[2810,'gap'],[3380,'low'],[3940,'block'],[4510,'gap'],[5100,'block'],[5670,'low'],[6240,'gap'],[6820,'block'],[7400,'low'],[7980,'gap'],[8620,'block'],[9140,'low']],items:[350,900,1450,2010,2570,3140,3700,4270,4850,5430,6000,6580,7150,7740,8330,8910]}
  ];
  let mode='title',selected=0,player=null,worldX=0,elapsed=0,last=0,shake=0,slow=1,lastBeatNumber=-1,toastUntil=0,items=[],audioCtx=null,soundOn=true,keys={},shortcut=false;
  const audioButton=$('soundToggle');
  function show(which){Object.values(screens).forEach(s=>s.hidden=true);if(which)screens[which].hidden=false;}
  function formatTime(s){const m=Math.floor(s/60),sec=(s%60).toFixed(1).padStart(4,'0');return `${String(m).padStart(2,'0')}:${sec}`;}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastUntil=performance.now()+1450;}
  function playTone(freq,duration=.08,wave='sine',volume=.025){if(!soundOn)return;try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=wave;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch(_){}}
  function setSound(){soundOn=!soundOn;audioButton.classList.toggle('muted',!soundOn);audioButton.setAttribute('aria-label',soundOn?'Desativar som':'Ativar som');if(soundOn)playTone(440,.08);}
  function toggleLevelCards(){document.querySelectorAll('.level-card').forEach((c,i)=>c.classList.toggle('selected',i===selected));}
  function startFromTitle(){mode='levels';show('levels');toggleLevelCards();}
