  function jump(){if(mode!=='playing')return;const p=player;if(p.hang){p.hang=false;p.vy=-570;p.jumps=1;p.onGround=false;p.spin=.35;playTone(540,.08,'triangle');return;}if(p.onGround){p.vy=-525;p.jumps=1;p.onGround=false;p.combo=0;slow=1;playTone(420,.07,'sine');return;}if(p.jumps===1){const cfg=levels[selected],phase=(elapsed%cfg.beat)/cfg.beat,nearBeat=phase<.17||phase>.83;if(nearBeat){p.vy=-690;p.combo++;p.bestCombo=Math.max(p.bestCombo,p.combo);p.spin=.48;playTone(880,.12,'triangle',.05);toast('SALTO NO TEMPO!');}else{p.vy=-395;p.combo=0;slow=.72;playTone(180,.1,'sine');toast('FORA DA BATIDA — PERDEU IMPULSO');}$('comboCount').textContent=String(p.combo);p.jumps=2;p.onGround=false;}}
  function slide(){if(mode!=='playing'||player.hang)return;player.slide=.48;playTone(250,.05,'triangle',.018);}
  function grab(){if(mode!=='playing')return;const p=player;if(p.hang){p.hang=false;p.vy=-570;p.jumps=1;p.onGround=false;return;}const nearby=levels[selected].obstacles.some(([x,type])=>type==='block'&&Math.abs(x-(worldX+p.x))<100);if(nearby&&!p.onGround&&p.y>GROUND-175){p.hang=true;p.hangTimer=0;p.vy=0;p.y=GROUND-145;p.combo++;p.bestCombo=Math.max(p.bestCombo,p.combo);$('comboCount').textContent=String(p.combo);toast('AGARRADO! TOQUE PARA SUBIR');playTone(620,.1,'sine');}else if(!p.onGround){p.vy=Math.min(p.vy,100);}}
  function activate(action){if(action==='jump')jump();if(action==='slide')slide();if(action==='grab')grab();}
  function update(dt,now){if(mode!=='playing')return;dt=Math.min(dt,.035);elapsed+=dt;const cfg=levels[selected],p=player;if(p.flash>0)p.flash-=dt;if(p.spin>0)p.spin-=dt;if(p.slide>0)p.slide-=dt;if(shake>0)shake-=dt;
    const beatNo=Math.floor(elapsed/cfg.beat);if(beatNo!==lastBeatNumber){lastBeatNumber=beatNo;playTone(220,.025,'sine',.009);}ui.timer.textContent=formatTime(elapsed);$('progressBar').style.width=`${Math.min(100,worldX/cfg.length*100)}%`;const phase=(elapsed%cfg.beat)/cfg.beat;ui.beat.classList.toggle('strong',phase<.12||phase>.88);if(now>toastUntil)ui.toast.classList.remove('show');
    const speed=(p.hang?0:220*slow)*(p.slide?1.12:1);if(!p.hang)worldX+=speed*dt;if(p.hang){p.hangTimer+=dt;if(p.hangTimer>1.5){p.hang=false;p.vy=-460;p.jumps=1;p.onGround=false;}}
