    for(const item of items){if(!item.got&&Math.abs(item.x-worldX-p.x)<30&&Math.abs(item.y-p.y-20)<62){item.got=true;p.notes++;$('noteCount').textContent=String(p.notes);toast(p.notes%4===0?'ATALHO ABERTO!':'NOTA COLETADA');if(p.notes%4===0)shortcut=true;playTone(990,.12,'triangle',.04);}}
